-- =====================================================================
-- V1 온톨로지 테이블 (온톨로지 MVP ERD v2, 18개)
-- 원본: ERD 문서 첨부 ddl.sql (2026-10-27판). 스키마 platform은 Flyway가 만들고 search_path도 맞춘다.
-- 운영 테이블(account, proposal_item, permission)을 가리키는 FK는 V3에서 건다.
--
-- 원칙
--   * PK는 bigint GENERATED BY DEFAULT AS IDENTITY
--   * updated_at, row_version은 애플리케이션(JPA @Version, Auditing)이 갱신한다
--   * 이 스키마에 쓰는 것은 Spring Boot(실행 엔진·Handler)와 수집 배치뿐이다. FastAPI는 읽기 전용 계정으로 읽는다
--   * 트리거 함수는 연결의 search_path와 무관하게 동작하도록 search_path를 고정했다
--   * [결정 U번호]·[미정 U번호] 주석은 ERD 문서의 결정 항목 번호다
-- =====================================================================

CREATE EXTENSION IF NOT EXISTS pg_trgm;   -- display_name 부분 검색용

-- ---------------------------------------------------------------------
-- 1. 정의
-- ---------------------------------------------------------------------

CREATE TABLE object_type (
    id                  bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    code                varchar(100) NOT NULL UNIQUE,
    name                varchar(200) NOT NULL,
    description         text,
    synonyms            jsonb        NOT NULL DEFAULT '[]'::jsonb,
    access_group        varchar(100),                 -- [미정 U5] 데이터 범위 묶음(예: concept.json tab)
    display_property_id bigint,                       -- FK는 property_definition 생성 뒤 추가
    origin              varchar(20)  NOT NULL DEFAULT 'MANUAL',
    proposal_item_id    bigint,                       -- → proposal_item.id (운영 ERD)
    created_at          timestamptz  NOT NULL DEFAULT now(),
    created_by          bigint,                       -- → account.id (운영 ERD)
    updated_at          timestamptz  NOT NULL DEFAULT now(),
    updated_by          bigint,
    row_version         integer      NOT NULL DEFAULT 0,
    CONSTRAINT ck_object_type_synonyms CHECK (jsonb_typeof(synonyms) = 'array'),
    CONSTRAINT ck_object_type_origin   CHECK (origin IN ('AI_PROPOSAL', 'MANUAL', 'SEED')),
    CONSTRAINT ck_object_type_proposal CHECK (origin <> 'AI_PROPOSAL' OR proposal_item_id IS NOT NULL)
);
COMMENT ON TABLE  object_type      IS '업무 대상의 종류. 예: EQUIPMENT(설비)';
COMMENT ON COLUMN object_type.code IS '프로그램용 코드. 한 번 쓰이면 바꾸지 않는다';

CREATE TABLE property_definition (
    id               bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    object_type_id   bigint       NOT NULL REFERENCES object_type (id) ON DELETE RESTRICT,
    code             varchar(100) NOT NULL,
    name             varchar(200) NOT NULL,
    data_type        varchar(20)  NOT NULL,
    description      text,
    is_identifier    boolean      NOT NULL DEFAULT false,
    is_required      boolean      NOT NULL DEFAULT false,
    unit             varchar(50),
    constraints      jsonb        NOT NULL DEFAULT '{}'::jsonb,
    sensitivity      varchar(20)  NOT NULL DEFAULT 'NORMAL',  -- [미정 U5] 값 체계
    temporal_role    varchar(20),                             -- 업무 기준일(AS_OF)·사건 시각(EVENT_TIME) 표시
    origin           varchar(20)  NOT NULL DEFAULT 'MANUAL',
    proposal_item_id bigint,
    created_at       timestamptz  NOT NULL DEFAULT now(),
    created_by       bigint,
    updated_at       timestamptz  NOT NULL DEFAULT now(),
    updated_by       bigint,
    row_version      integer      NOT NULL DEFAULT 0,
    CONSTRAINT uq_property_definition_code UNIQUE (object_type_id, code),
    CONSTRAINT uq_property_definition_type UNIQUE (object_type_id, id),   -- object_type.display_property_id 복합 FK용
    CONSTRAINT ck_property_definition_data_type
        CHECK (data_type IN ('STRING', 'INTEGER', 'DECIMAL', 'DATE', 'TIME', 'DATETIME', 'BOOLEAN', 'JSON')),
    CONSTRAINT ck_property_definition_constraints CHECK (jsonb_typeof(constraints) = 'object'),
    CONSTRAINT ck_property_definition_sensitivity CHECK (sensitivity IN ('NORMAL', 'RESTRICTED')),
    CONSTRAINT ck_property_definition_temporal
        CHECK (temporal_role IS NULL
               OR (temporal_role IN ('AS_OF', 'EVENT_TIME') AND data_type IN ('DATE', 'TIME', 'DATETIME'))),
    CONSTRAINT ck_property_definition_origin      CHECK (origin IN ('AI_PROPOSAL', 'MANUAL', 'SEED')),
    CONSTRAINT ck_property_definition_proposal    CHECK (origin <> 'AI_PROPOSAL' OR proposal_item_id IS NOT NULL)
);
COMMENT ON TABLE  property_definition      IS '객체 유형의 속성과 값 형식. 실제 값은 object_instance.properties';
COMMENT ON COLUMN property_definition.code IS 'properties JSON의 키. 활성 뒤 변경 금지, 바꾸려면 새 속성';
COMMENT ON COLUMN property_definition.temporal_role IS 'AS_OF=이 객체 값의 업무 기준일(예: 장부가 기준일), EVENT_TIME=사건 발생 시각. 답변의 기준 시점은 이 속성으로, 수집 시점은 object_instance.last_synced_at으로 구분한다';

-- 표시 이름으로 쓸 속성은 같은 객체 유형의 속성이어야 한다(복합 FK로 강제)
ALTER TABLE object_type
    ADD CONSTRAINT fk_object_type_display_property
    FOREIGN KEY (id, display_property_id)
    REFERENCES property_definition (object_type_id, id) ON DELETE RESTRICT;

CREATE TABLE link_type (
    id               bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    code             varchar(100) NOT NULL UNIQUE,
    name             varchar(200) NOT NULL,
    source_type_id   bigint       NOT NULL REFERENCES object_type (id) ON DELETE RESTRICT,
    target_type_id   bigint       NOT NULL REFERENCES object_type (id) ON DELETE RESTRICT,
    cardinality      varchar(20)  NOT NULL,
    description      text         NOT NULL,
    origin           varchar(20)  NOT NULL DEFAULT 'MANUAL',
    proposal_item_id bigint,
    created_at       timestamptz  NOT NULL DEFAULT now(),
    created_by       bigint,
    updated_at       timestamptz  NOT NULL DEFAULT now(),
    updated_by       bigint,
    row_version      integer      NOT NULL DEFAULT 0,
    CONSTRAINT ck_link_type_cardinality
        CHECK (cardinality IN ('ONE_TO_ONE', 'ONE_TO_MANY', 'MANY_TO_ONE', 'MANY_TO_MANY')),
    CONSTRAINT ck_link_type_origin   CHECK (origin IN ('AI_PROPOSAL', 'MANUAL', 'SEED')),
    CONSTRAINT ck_link_type_proposal CHECK (origin <> 'AI_PROPOSAL' OR proposal_item_id IS NOT NULL)
);
COMMENT ON TABLE link_type IS '객체 유형 사이 관계의 의미. 실행 규칙은 link_mapping';

-- ---------------------------------------------------------------------
-- 2. 원천
-- ---------------------------------------------------------------------

CREATE TABLE data_source (
    id                    bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    code                  varchar(100) NOT NULL UNIQUE,
    name                  varchar(200) NOT NULL,
    source_kind           varchar(20)  NOT NULL,       -- [결정 U1] 원천 DB에 읽기 전용 계정으로 직접 접속. REST는 두지 않는다
    connection_config     jsonb        NOT NULL DEFAULT '{}'::jsonb,  -- 비밀이 아닌 접속 설정(host, port, database 등). 계정·비밀번호는 data_source_credential
    connection_status     varchar(20)  NOT NULL DEFAULT 'UNVERIFIED',
    last_checked_at       timestamptz,
    sync_enabled          boolean      NOT NULL DEFAULT false,
    sync_interval_minutes integer,
    created_at            timestamptz  NOT NULL DEFAULT now(),
    created_by            bigint,
    updated_at            timestamptz  NOT NULL DEFAULT now(),
    updated_by            bigint,
    row_version           integer      NOT NULL DEFAULT 0,
    CONSTRAINT ck_data_source_kind     CHECK (source_kind IN ('POSTGRES', 'CSV', 'DOCUMENT')),
    CONSTRAINT ck_data_source_status   CHECK (connection_status IN ('UNVERIFIED', 'CONNECTED', 'FAILED')),
    CONSTRAINT ck_data_source_interval CHECK (sync_interval_minutes IS NULL OR sync_interval_minutes > 0),
    CONSTRAINT ck_data_source_sync     CHECK (NOT sync_enabled OR sync_interval_minutes IS NOT NULL),
    CONSTRAINT ck_data_source_config   CHECK (jsonb_typeof(connection_config) = 'object'
                                              AND NOT (connection_config ?| ARRAY['password', 'secret', 'api_key']))  -- 비밀값은 여기 넣지 않는다
);
COMMENT ON TABLE data_source IS '원천 시스템(ERP, MES 등)과 연결 상태, 자동 수집 주기. 체크포인트는 원천 테이블 단위(source_resource)';

-- 원천 접속 계정. 비밀번호는 양방향 암호화(AES-256-GCM)해 저장하고, 접속할 때만 메모리에서 푼다.
-- 암호화 키는 DB가 아니라 Jenkins Credentials에 두고 배포 때 주입한다. key_version으로 키 교체 뒤에도 옛 값을 푼다.
-- purpose: SYNC = 배치(수집·연결 검사, 금지 컬럼만 제외), AI = FastAPI 제안기(외부 LLM으로 보내면 안 되는 제한 컬럼까지 제외).
-- 금지 컬럼(주민번호·연락처·계좌 등)은 원천 DB의 컬럼 권한으로 막아 두 계정 모두 읽지 못한다(2026-10-26, A5).
-- 백엔드는 등록·변경 때 암호화만 하고 원천에는 접속하지 않는다. 키를 어느 컨테이너에 주입할지는 구현 단계에서 정한다.
CREATE TABLE data_source_credential (
    id                bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    data_source_id    bigint       NOT NULL REFERENCES data_source (id) ON DELETE CASCADE,
    purpose           varchar(10)  NOT NULL,
    username          varchar(200) NOT NULL,
    secret_ciphertext bytea        NOT NULL,
    secret_nonce      bytea        NOT NULL,
    key_version       integer      NOT NULL,
    rotated_at        timestamptz  NOT NULL DEFAULT now(),
    created_by        bigint,
    CONSTRAINT uq_data_source_credential UNIQUE (data_source_id, purpose),
    CONSTRAINT ck_data_source_credential_purpose CHECK (purpose IN ('SYNC', 'AI')),
    CONSTRAINT ck_data_source_credential_key     CHECK (key_version > 0),
    CONSTRAINT ck_data_source_credential_nonce   CHECK (octet_length(secret_nonce) = 12)
);
COMMENT ON TABLE data_source_credential IS '원천 접속 계정. 비밀번호는 암호문만 저장하고 화면·API·로그에는 내보내지 않는다(A1, B10)';
COMMENT ON COLUMN data_source.source_kind IS 'POSTGRES = 원천 DB 직접 접속(읽기 전용 계정, 보안 그룹은 플랫폼 서버 IP만 허용). 스키마는 information_schema로, 변경분은 변경 이력 테이블을 SQL로 읽는다(U1 결정)';

-- 연결 검사·테이블/컬럼 목록 갱신 작업(API 013~015). 백엔드가 QUEUED로 넣고 배치가 SYNC·AI 계정으로 실행한다(2026-10-27).
CREATE TABLE source_connection_check (
    id             bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    data_source_id bigint      NOT NULL REFERENCES data_source (id) ON DELETE CASCADE,
    status         varchar(20) NOT NULL DEFAULT 'QUEUED',
    requested_by   bigint      NOT NULL,                  -- → account.id (운영 ERD)
    requested_at   timestamptz NOT NULL DEFAULT now(),
    started_at     timestamptz,
    finished_at    timestamptz,
    result         jsonb       NOT NULL DEFAULT '{}'::jsonb,   -- 계정별 접속 결과, 읽을 수 있는 자원·컬럼 수. 비밀값 금지
    error_message  text,
    CONSTRAINT ck_source_connection_check_status   CHECK (status IN ('QUEUED', 'RUNNING', 'SUCCEEDED', 'FAILED')),
    CONSTRAINT ck_source_connection_check_started  CHECK ((status = 'QUEUED') = (started_at IS NULL)),
    CONSTRAINT ck_source_connection_check_finished CHECK ((status IN ('SUCCEEDED', 'FAILED')) = (finished_at IS NOT NULL)),
    CONSTRAINT ck_source_connection_check_result   CHECK (jsonb_typeof(result) = 'object'),
    CONSTRAINT ck_source_connection_check_error    CHECK (status <> 'FAILED' OR error_message IS NOT NULL)
);
COMMENT ON TABLE source_connection_check IS '원천 연결 검사 작업. 성공하면 data_source.connection_status와 source_resource·source_column(카탈로그)을 갱신한다. 원천마다 대기·실행 중인 검사는 하나';
CREATE UNIQUE INDEX uq_source_connection_check_active ON source_connection_check (data_source_id) WHERE status IN ('QUEUED', 'RUNNING');

CREATE TABLE source_resource (
    id              bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    data_source_id  bigint       NOT NULL REFERENCES data_source (id) ON DELETE RESTRICT,
    resource_key    varchar(300) NOT NULL,
    resource_kind   varchar(20)  NOT NULL,
    source_metadata jsonb        NOT NULL DEFAULT '{}'::jsonb,
    is_readable     boolean      NOT NULL DEFAULT false,      -- SYNC 계정 기준. AI 계정이 못 읽는 테이블은 분석 실행 때 실패 사유로 알린다(2026-10-27)
    initial_loaded_at timestamptz,                        -- 첫 전체 적재 완료 시각. NULL이면 아직 적재 전(새로 매핑된 자원)
    last_applied_change_seq bigint,                       -- 이 테이블에 대해 성공적으로 반영한 마지막 변경 번호(테이블 단위 체크포인트)
    last_seen_at    timestamptz  NOT NULL DEFAULT now(),
    CONSTRAINT uq_source_resource UNIQUE (data_source_id, resource_key),
    CONSTRAINT uq_source_resource_source UNIQUE (id, data_source_id),   -- sync_run_resource 복합 FK용
    CONSTRAINT ck_source_resource_kind     CHECK (resource_kind IN ('TABLE', 'VIEW', 'DOCUMENT_SET', 'FILE')),
    CONSTRAINT ck_source_resource_metadata CHECK (jsonb_typeof(source_metadata) = 'object'),
    CONSTRAINT ck_source_resource_seq      CHECK (last_applied_change_seq IS NULL OR last_applied_change_seq >= 0)
);
COMMENT ON TABLE source_resource IS '원천 안의 표·뷰·문서 집합. 연결 확인 때 읽을 수 있는 자원 목록';
COMMENT ON COLUMN source_resource.last_applied_change_seq IS '[2026-10-26 A2] 체크포인트를 원천 단위에서 테이블 단위로 옮겼다. 질문 시 동기화가 필요한 테이블만 읽어도 다른 테이블의 변경분을 건너뛰지 않는다. 원천 변경 이력은 테이블 이름·행 PK·변경 종류·번호만 담는다(값은 담지 않음, A5). 객체 반영과 같은 트랜잭션에서만 전진한다';

CREATE TABLE source_column (
    id                 bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    source_resource_id bigint       NOT NULL REFERENCES source_resource (id) ON DELETE RESTRICT,
    column_name        varchar(200) NOT NULL,
    source_data_type   varchar(100) NOT NULL,
    is_nullable        boolean      NOT NULL,
    is_key_part        boolean      NOT NULL DEFAULT false,
    ordinal_position   integer      NOT NULL,
    source_comment     text,
    is_present         boolean      NOT NULL DEFAULT true,
    last_seen_at       timestamptz  NOT NULL DEFAULT now(),
    CONSTRAINT uq_source_column UNIQUE (source_resource_id, column_name),
    CONSTRAINT uq_source_column_resource UNIQUE (id, source_resource_id),   -- property_source_mapping 복합 FK용
    CONSTRAINT ck_source_column_position CHECK (ordinal_position > 0)
);
COMMENT ON TABLE  source_column            IS '원천 컬럼 스냅샷(SYNC 계정 기준). 원천에서 사라져도 지우지 않고 is_present=false. 금지 컬럼은 원천 권한으로 막혀 여기 나타나지 않는다(2026-10-27: 민감 칸 삭제)';
COMMENT ON COLUMN source_column.is_present IS '컬럼 목록을 성공적으로 읽었을 때만 false로 바꾼다. 조회 실패·권한 제한은 컬럼 삭제로 보지 않는다';

-- 원천 표본·매핑 미리보기 작업(API 016, FN-MAP-04). 화면이 원천 행을 봐야 하지만 백엔드는 원천에 붙지 않으므로
-- 백엔드가 QUEUED로 넣고(NOTIFY로 배치를 깨움) 배치가 SYNC 계정으로 읽어 result에 채운다(2026-10-27).
-- 미리보기는 수집과 같은 Java 변환 엔진으로 객체 모양을 만들고 DB에는 쓰지 않는다. 원천 값이 들어 있으므로 expires_at 뒤 배치가 지운다.
CREATE TABLE source_preview (
    id                 bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    source_resource_id bigint      NOT NULL REFERENCES source_resource (id) ON DELETE CASCADE,
    preview_kind       varchar(20) NOT NULL,
    request            jsonb       NOT NULL DEFAULT '{}'::jsonb,   -- MAPPING_PREVIEW: 저장 전 매핑 초안 {mapping: {...}}
    row_limit          smallint    NOT NULL DEFAULT 20,
    status             varchar(20) NOT NULL DEFAULT 'QUEUED',
    requested_by       bigint      NOT NULL,                       -- → account.id (운영 ERD)
    requested_at       timestamptz NOT NULL DEFAULT now(),
    started_at         timestamptz,
    finished_at        timestamptz,
    result             jsonb,                                      -- SAMPLE: {columns, rows} / MAPPING_PREVIEW: {objects, rowErrors}
    error_message      text,
    expires_at         timestamptz NOT NULL DEFAULT now() + interval '1 hour',
    CONSTRAINT ck_source_preview_kind     CHECK (preview_kind IN ('SAMPLE', 'MAPPING_PREVIEW')),
    CONSTRAINT ck_source_preview_request  CHECK (jsonb_typeof(request) = 'object'
                                                 AND (preview_kind <> 'MAPPING_PREVIEW' OR request ? 'mapping')),
    CONSTRAINT ck_source_preview_limit    CHECK (row_limit BETWEEN 1 AND 20),
    CONSTRAINT ck_source_preview_status   CHECK (status IN ('QUEUED', 'RUNNING', 'SUCCEEDED', 'FAILED')),
    CONSTRAINT ck_source_preview_started  CHECK ((status = 'QUEUED') = (started_at IS NULL)),
    CONSTRAINT ck_source_preview_finished CHECK ((status IN ('SUCCEEDED', 'FAILED')) = (finished_at IS NOT NULL)),
    CONSTRAINT ck_source_preview_result   CHECK ((status = 'SUCCEEDED') = (result IS NOT NULL)
                                                 AND (result IS NULL OR jsonb_typeof(result) = 'object')),
    CONSTRAINT ck_source_preview_error    CHECK ((status = 'FAILED') = (error_message IS NOT NULL)),
    CONSTRAINT ck_source_preview_expires  CHECK (expires_at > requested_at)
);
COMMENT ON TABLE source_preview IS '원천 표본(016)·매핑 미리보기 작업. 짧게 쓰고 버리는 표라 이력은 action_execution(SOURCE_PREVIEW: 누가 어느 테이블을 봤는지, 행 값은 넣지 않음)에 남긴다';

CREATE TABLE object_source_mapping (
    id                 bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    source_resource_id bigint      NOT NULL REFERENCES source_resource (id) ON DELETE RESTRICT,
    object_type_id     bigint      NOT NULL REFERENCES object_type (id) ON DELETE RESTRICT,
    key_columns        jsonb       NOT NULL,
    row_filter         jsonb       NOT NULL DEFAULT '{}'::jsonb,
    is_active          boolean     NOT NULL DEFAULT true,     -- false면 수집하지 않는다(객체는 남는다)
    origin             varchar(20) NOT NULL DEFAULT 'MANUAL',
    proposal_item_id   bigint,
    created_at         timestamptz NOT NULL DEFAULT now(),
    created_by         bigint,
    updated_at         timestamptz NOT NULL DEFAULT now(),
    updated_by         bigint,
    row_version        integer     NOT NULL DEFAULT 0,
    CONSTRAINT uq_object_source_mapping_type UNIQUE (id, object_type_id),   -- object_instance 복합 FK용
    CONSTRAINT uq_object_source_mapping_res  UNIQUE (id, source_resource_id), -- property_source_mapping 복합 FK용
    CONSTRAINT ck_object_source_mapping_keys
        CHECK (jsonb_typeof(key_columns) = 'array' AND jsonb_array_length(key_columns) > 0),
    CONSTRAINT ck_object_source_mapping_filter   CHECK (jsonb_typeof(row_filter) = 'object'),
    CONSTRAINT ck_object_source_mapping_origin   CHECK (origin IN ('AI_PROPOSAL', 'MANUAL', 'SEED')),
    CONSTRAINT ck_object_source_mapping_proposal CHECK (origin <> 'AI_PROPOSAL' OR proposal_item_id IS NOT NULL)
);
COMMENT ON TABLE object_source_mapping IS '원천 자원의 행에서 어떤 객체 유형을 만들지와 원천 키. 관리자가 직접 편집한다(2026-10-27). 객체가 만들어진 뒤에는 키 컬럼을 바꿀 수 없다(트리거). 컬럼·변환·행 조건을 바꾸면 그 테이블의 initial_loaded_at을 비워 다음 수집이 전체 다시 적재한다';
COMMENT ON COLUMN object_source_mapping.is_active IS '수집 중지. 객체가 있으면 매핑을 지울 수 없으므로(RESTRICT) 더 이상 가져오지 않을 때는 false로 둔다';

-- 객체가 만들어진 매핑의 키 컬럼·원천 자원·객체 유형은 바꿀 수 없다. 바꾸면 같은 원천 행이 다른 객체가 되어
-- 연결·문제·재배정 계획이 끊긴다. 바꾸려면 매핑을 새로 만든다(2026-10-27)
CREATE FUNCTION guard_object_source_mapping_key() RETURNS trigger LANGUAGE plpgsql
    SET search_path = platform, pg_temp
AS $$
BEGIN
    IF (NEW.key_columns IS DISTINCT FROM OLD.key_columns
        OR NEW.source_resource_id IS DISTINCT FROM OLD.source_resource_id
        OR NEW.object_type_id IS DISTINCT FROM OLD.object_type_id)
       AND EXISTS (SELECT 1 FROM object_instance WHERE source_mapping_id = OLD.id) THEN
        RAISE EXCEPTION '객체가 만들어진 매핑(%)의 키 컬럼·원천 자원·객체 유형은 바꿀 수 없습니다. 매핑을 새로 만드세요', OLD.id;
    END IF;
    RETURN NEW;
END $$;
CREATE TRIGGER trg_object_source_mapping_key BEFORE UPDATE ON object_source_mapping
    FOR EACH ROW EXECUTE FUNCTION guard_object_source_mapping_key();

CREATE TABLE property_source_mapping (
    id                     bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    source_mapping_id      bigint      NOT NULL,
    source_resource_id     bigint      NOT NULL,          -- 소속 매핑의 원천 자원(소속 강제를 위해 중복 보관)
    property_definition_id bigint      NOT NULL REFERENCES property_definition (id) ON DELETE RESTRICT,
    source_column_id       bigint,                         -- 표 컬럼이면 채움
    source_path            text,                           -- 문서 필드 경로면 채움(둘 중 하나만)
    transform_steps        jsonb       NOT NULL DEFAULT '[]'::jsonb,
    created_at             timestamptz NOT NULL DEFAULT now(),
    created_by             bigint,
    updated_at             timestamptz NOT NULL DEFAULT now(),
    updated_by             bigint,
    row_version            integer     NOT NULL DEFAULT 0,
    -- 매핑과 컬럼이 같은 원천 자원에 속해야 한다(복합 FK 2개로 강제)
    CONSTRAINT fk_property_source_mapping_mapping
        FOREIGN KEY (source_mapping_id, source_resource_id)
        REFERENCES object_source_mapping (id, source_resource_id) ON DELETE RESTRICT,
    CONSTRAINT fk_property_source_mapping_column
        FOREIGN KEY (source_column_id, source_resource_id)
        REFERENCES source_column (id, source_resource_id) ON DELETE RESTRICT,
    CONSTRAINT uq_property_source_mapping UNIQUE (source_mapping_id, property_definition_id),
    CONSTRAINT ck_property_source_mapping_source CHECK ((source_column_id IS NULL) <> (source_path IS NULL)),
    CONSTRAINT ck_property_source_mapping_transforms CHECK (jsonb_typeof(transform_steps) = 'array')
);
COMMENT ON TABLE property_source_mapping IS '원천 컬럼 값을 객체 속성에 넣는 방법. 속성이 매핑의 객체 유형에 속하는지는 Handler가 검사';

-- ---------------------------------------------------------------------
-- 3. 관계 규칙
-- ---------------------------------------------------------------------

CREATE TABLE link_mapping (
    id               bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    link_type_id     bigint       NOT NULL REFERENCES link_type (id) ON DELETE RESTRICT,
    code             varchar(100) NOT NULL,
    revision         integer      NOT NULL,
    source_filter    jsonb        NOT NULL DEFAULT '{}'::jsonb,
    target_filter    jsonb        NOT NULL DEFAULT '{}'::jsonb,
    description      text,
    status           varchar(20)  NOT NULL DEFAULT 'ACTIVE',
    retired_at       timestamptz,
    origin           varchar(20)  NOT NULL DEFAULT 'MANUAL',
    proposal_item_id bigint,
    created_at       timestamptz  NOT NULL DEFAULT now(),
    created_by       bigint,
    CONSTRAINT uq_link_mapping_revision UNIQUE (code, revision),
    CONSTRAINT uq_link_mapping_type     UNIQUE (id, link_type_id),   -- object_link 복합 FK용
    CONSTRAINT ck_link_mapping_revision CHECK (revision > 0),
    CONSTRAINT ck_link_mapping_filters
        CHECK (jsonb_typeof(source_filter) = 'object' AND jsonb_typeof(target_filter) = 'object'),
    CONSTRAINT ck_link_mapping_status   CHECK (status IN ('ACTIVE', 'RETIRED')),
    CONSTRAINT ck_link_mapping_retired  CHECK ((status = 'RETIRED') = (retired_at IS NOT NULL)),
    CONSTRAINT ck_link_mapping_origin   CHECK (origin IN ('AI_PROPOSAL', 'MANUAL', 'SEED')),
    CONSTRAINT ck_link_mapping_proposal CHECK (origin <> 'AI_PROPOSAL' OR proposal_item_id IS NOT NULL)
);
-- 규칙 코드마다 현재 쓰는 개정본은 하나
CREATE UNIQUE INDEX uq_link_mapping_active ON link_mapping (code) WHERE status = 'ACTIVE';
COMMENT ON TABLE link_mapping IS '관계 연결 규칙 개정본. 생성 후 내용 불변(status, retired_at만 변경). [결정 U10] 승인 전 규칙은 운영 ERD 제안 항목에만 두고, 여기에는 승인된 개정본만 넣는다';

CREATE TABLE link_mapping_condition (
    id                 bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    link_mapping_id    bigint      NOT NULL REFERENCES link_mapping (id) ON DELETE RESTRICT,
    source_property_id bigint      NOT NULL REFERENCES property_definition (id) ON DELETE RESTRICT,
    target_property_id bigint      NOT NULL REFERENCES property_definition (id) ON DELETE RESTRICT,
    sequence_no        integer     NOT NULL,
    operator           varchar(20) NOT NULL DEFAULT 'EQ',
    source_transforms  jsonb       NOT NULL DEFAULT '[]'::jsonb,
    target_transforms  jsonb       NOT NULL DEFAULT '[]'::jsonb,
    created_at         timestamptz NOT NULL DEFAULT now(),
    created_by         bigint,
    CONSTRAINT uq_link_mapping_condition UNIQUE (link_mapping_id, sequence_no),
    CONSTRAINT ck_link_mapping_condition_seq CHECK (sequence_no > 0),
    CONSTRAINT ck_link_mapping_condition_op  CHECK (operator IN ('EQ')),
    CONSTRAINT ck_link_mapping_condition_transforms
        CHECK (jsonb_typeof(source_transforms) = 'array' AND jsonb_typeof(target_transforms) = 'array')
);
COMMENT ON TABLE link_mapping_condition IS '규칙의 속성 비교 항목. 항목끼리 AND. 속성이 관계 유형 양 끝 유형에 속하는지는 Handler가 검사';

-- 규칙 개정본은 생성 후 내용을 바꾸지 않는다. link_mapping은 status·retired_at만 바뀔 수 있고,
-- 비교 항목은 규칙을 만든 트랜잭션 안에서만 추가할 수 있으며 수정·삭제할 수 없다.
CREATE FUNCTION guard_link_mapping_update() RETURNS trigger LANGUAGE plpgsql
    SET search_path = platform, pg_temp   -- 애플리케이션 연결의 search_path와 무관하게 동작
AS $$
BEGIN
    IF (NEW.link_type_id, NEW.code, NEW.revision, NEW.source_filter, NEW.target_filter, NEW.description,
        NEW.origin, NEW.proposal_item_id, NEW.created_at, NEW.created_by)
       IS DISTINCT FROM
       (OLD.link_type_id, OLD.code, OLD.revision, OLD.source_filter, OLD.target_filter, OLD.description,
        OLD.origin, OLD.proposal_item_id, OLD.created_at, OLD.created_by) THEN
        RAISE EXCEPTION 'link_mapping % 개정본의 내용은 바꿀 수 없습니다. 새 revision을 만드세요', OLD.id;
    END IF;
    IF OLD.status = 'RETIRED' AND NEW.status = 'ACTIVE' THEN
        RAISE EXCEPTION 'RETIRED 개정본을 다시 ACTIVE로 바꿀 수 없습니다';
    END IF;
    RETURN NEW;
END $$;
CREATE TRIGGER trg_link_mapping_guard BEFORE UPDATE ON link_mapping
    FOR EACH ROW EXECUTE FUNCTION guard_link_mapping_update();

CREATE FUNCTION guard_link_mapping_condition() RETURNS trigger LANGUAGE plpgsql
    SET search_path = platform, pg_temp   -- 애플리케이션 연결의 search_path와 무관하게 동작
AS $$
BEGIN
    IF TG_OP = 'INSERT' THEN
        -- now()는 트랜잭션 시작 시각이므로, 같은 트랜잭션에서 만든 규칙에만 항목을 추가할 수 있다
        IF NOT EXISTS (SELECT 1 FROM link_mapping m WHERE m.id = NEW.link_mapping_id AND m.created_at = now()) THEN
            RAISE EXCEPTION '이미 만들어진 규칙 개정본(%)에는 비교 항목을 추가할 수 없습니다', NEW.link_mapping_id;
        END IF;
        RETURN NEW;
    END IF;
    RAISE EXCEPTION '규칙 비교 항목은 수정·삭제할 수 없습니다. 새 revision을 만드세요';
END $$;
CREATE TRIGGER trg_link_mapping_condition_guard BEFORE INSERT OR UPDATE OR DELETE ON link_mapping_condition
    FOR EACH ROW EXECUTE FUNCTION guard_link_mapping_condition();

-- ---------------------------------------------------------------------
-- 4. 수집 실행 (object_instance가 참조하므로 먼저 만든다)
-- ---------------------------------------------------------------------

CREATE TABLE sync_run (
    id              bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    data_source_id  bigint      NOT NULL REFERENCES data_source (id) ON DELETE RESTRICT,
    trigger_kind    varchar(20) NOT NULL,
    status          varchar(20) NOT NULL DEFAULT 'QUEUED',
    requested_at    timestamptz NOT NULL DEFAULT now(),
    started_at      timestamptz,                          -- 배치가 작업을 가져가 시작한 시각
    heartbeat_at    timestamptz,                          -- [결정 U3] 실행 중 배치가 주기적으로 갱신. 오래 멈춘 RUNNING을 시간 초과로 정리하는 기준
    finished_at     timestamptz,
    error_message   text,
    requested_by    bigint,                               -- → account.id (운영 ERD). ON_DEMAND면 질문한 사용자
    CONSTRAINT uq_sync_run_source   UNIQUE (id, data_source_id),   -- sync_run_resource 복합 FK용
    CONSTRAINT ck_sync_run_trigger  CHECK (trigger_kind IN ('SCHEDULED', 'MANUAL', 'ON_DEMAND')),
    CONSTRAINT ck_sync_run_status   CHECK (status IN ('QUEUED', 'RUNNING', 'SUCCEEDED', 'FAILED')),
    CONSTRAINT ck_sync_run_started  CHECK ((status = 'QUEUED') = (started_at IS NULL)),
    CONSTRAINT ck_sync_run_finished CHECK ((status IN ('SUCCEEDED', 'FAILED')) = (finished_at IS NOT NULL)),
    CONSTRAINT ck_sync_run_time     CHECK (finished_at IS NULL OR finished_at >= started_at),
    CONSTRAINT ck_sync_run_requester CHECK (trigger_kind = 'SCHEDULED' OR requested_by IS NOT NULL),
    CONSTRAINT ck_sync_run_error    CHECK (status <> 'FAILED' OR error_message IS NOT NULL)
);
COMMENT ON TABLE sync_run IS '원천 수집 한 번(FN-BAT-02~04). 작업 표 방식: 백엔드가 QUEUED로 넣고 배치가 가져가 RUNNING으로 바꾼다(2026-10-27). SCHEDULED = 주기, MANUAL = 관리자 버튼, ON_DEMAND = Agent 질문에 필요한 테이블만(A2). 어떤 테이블을 어느 구간까지 읽었는지는 sync_run_resource';

-- 수집 실행의 테이블별 기록. 체크포인트가 테이블 단위라서 구간·건수·상태도 테이블마다 남긴다(A2).
-- 요청할 때 대상 테이블마다 QUEUED 행을 함께 넣는다.
CREATE TABLE sync_run_resource (
    sync_run_id        bigint      NOT NULL,
    data_source_id     bigint      NOT NULL,
    source_resource_id bigint      NOT NULL,
    mode               varchar(20) NOT NULL,                -- [결정 U2] 새로 매핑된(또는 매핑이 바뀐) 테이블은 FULL, 이후 INCREMENTAL
    status             varchar(20) NOT NULL DEFAULT 'QUEUED',
    from_change_seq    bigint,                               -- 이 테이블에 대해 반영한 변경 번호 구간
    to_change_seq      bigint,
    rows_read          integer     NOT NULL DEFAULT 0,
    rows_upserted      integer     NOT NULL DEFAULT 0,
    rows_deleted       integer     NOT NULL DEFAULT 0,
    started_at         timestamptz,
    finished_at        timestamptz,
    error_message      text,
    PRIMARY KEY (sync_run_id, source_resource_id),
    -- 실행과 테이블이 같은 원천이어야 한다
    CONSTRAINT fk_sync_run_resource_run
        FOREIGN KEY (sync_run_id, data_source_id) REFERENCES sync_run (id, data_source_id) ON DELETE CASCADE,
    CONSTRAINT fk_sync_run_resource_resource
        FOREIGN KEY (source_resource_id, data_source_id) REFERENCES source_resource (id, data_source_id) ON DELETE RESTRICT,
    CONSTRAINT ck_sync_run_resource_mode     CHECK (mode IN ('FULL', 'INCREMENTAL')),
    CONSTRAINT ck_sync_run_resource_status   CHECK (status IN ('QUEUED', 'RUNNING', 'SUCCEEDED', 'FAILED', 'SKIPPED')),
    CONSTRAINT ck_sync_run_resource_started  CHECK ((status = 'QUEUED') = (started_at IS NULL)),
    CONSTRAINT ck_sync_run_resource_finished CHECK ((status IN ('QUEUED', 'RUNNING')) = (finished_at IS NULL)),
    CONSTRAINT ck_sync_run_resource_counts   CHECK (rows_read >= 0 AND rows_upserted >= 0 AND rows_deleted >= 0),
    CONSTRAINT ck_sync_run_resource_error    CHECK (status <> 'FAILED' OR error_message IS NOT NULL),
    CONSTRAINT ck_sync_run_resource_range    CHECK (from_change_seq IS NULL OR to_change_seq IS NULL OR to_change_seq >= from_change_seq)
);
COMMENT ON TABLE sync_run_resource IS '수집 실행의 테이블별 구간·건수·상태. SKIPPED = 잠금을 받고 다시 확인했더니 읽을 변경분이 없었음(중복 방지, A4)';
-- [결정 U3 → A2·A4] 같은 테이블은 대기·실행 중인 수집이 하나만 있다. 대기 중이거나 실행 중이면 새로 만들지 않고 합류한다.
--   채팅 A가 {작업지시, 설비}, 채팅 B가 {설비, 수주}를 요청하면 B는 수주만 새로 넣고 설비는 A의 실행에 합류한다.
--   heartbeat_at이 일정 시간(예: 10분) 갱신되지 않은 실행은 배치가 FAILED(시간 초과)로 정리한 뒤 다시 읽는다.
--   잠금을 받은 뒤에는 체크포인트를 다시 읽어, 그 사이 다른 실행이 반영했으면 SKIPPED로 끝낸다(9-6).
CREATE UNIQUE INDEX uq_sync_run_resource_active ON sync_run_resource (source_resource_id) WHERE status IN ('QUEUED', 'RUNNING');

-- ---------------------------------------------------------------------
-- 5. 인스턴스
-- ---------------------------------------------------------------------

CREATE TABLE object_instance (
    id                 bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    object_type_id     bigint       NOT NULL REFERENCES object_type (id) ON DELETE RESTRICT,
    source_mapping_id  bigint,
    source_key         jsonb,
    display_name       varchar(300) NOT NULL,
    properties         jsonb        NOT NULL DEFAULT '{}'::jsonb,
    status             varchar(30)  NOT NULL DEFAULT 'ACTIVE',   -- [결정 U7] 원천 삭제는 논리 삭제(DELETED_AT_SOURCE)만. 물리 삭제 기능은 두지 않는다
    first_collected_at timestamptz  NOT NULL DEFAULT now(),
    last_synced_at     timestamptz,
    last_sync_run_id   bigint       REFERENCES sync_run (id) ON DELETE RESTRICT,
    created_by         bigint,                                    -- 플랫폼 객체 생성자 → account.id
    updated_at         timestamptz  NOT NULL DEFAULT now(),
    -- 원천 객체의 유형은 그 매핑이 만드는 유형과 같아야 한다(복합 FK로 강제, 플랫폼 객체는 검사 제외)
    CONSTRAINT fk_object_instance_mapping
        FOREIGN KEY (source_mapping_id, object_type_id)
        REFERENCES object_source_mapping (id, object_type_id) ON DELETE RESTRICT,
    CONSTRAINT ck_object_instance_source     CHECK ((source_mapping_id IS NULL) = (source_key IS NULL)),
    CONSTRAINT ck_object_instance_key        CHECK (source_key IS NULL OR jsonb_typeof(source_key) = 'object'),
    CONSTRAINT ck_object_instance_properties CHECK (jsonb_typeof(properties) = 'object'),
    CONSTRAINT ck_object_instance_status     CHECK (status IN ('ACTIVE', 'DELETED_AT_SOURCE')),
    CONSTRAINT ck_object_instance_platform   CHECK (source_mapping_id IS NOT NULL OR status = 'ACTIVE')
);
-- 원천 행 하나에 객체 하나. 배치는 이 키로 upsert한다:
--   INSERT ... ON CONFLICT (source_mapping_id, source_key) WHERE source_mapping_id IS NOT NULL DO UPDATE ...
CREATE UNIQUE INDEX uq_object_instance_source
    ON object_instance (source_mapping_id, source_key) WHERE source_mapping_id IS NOT NULL;
COMMENT ON TABLE  object_instance    IS '실제 객체. 수집이 반복돼도 id를 유지한다(지우고 다시 넣지 않음). 재배정 계획은 운영 ERD의 reassignment_plan에 저장';
COMMENT ON COLUMN object_instance.id IS '내부 식별자. 원천 객체는 (source_mapping_id, source_key)로 찾는다';
COMMENT ON COLUMN object_instance.last_synced_at IS '플랫폼에 마지막으로 반영된 시각(수집 시점). 업무 값의 기준일은 temporal_role=AS_OF 속성으로 따로 표시한다';
COMMENT ON COLUMN object_instance.last_sync_run_id IS '마지막 반영 수집 실행. 같은 원천의 실행인지는 배치가 검사한다. 과거 실행의 변경 대상은 원천 변경 이력으로 다시 찾는다';

CREATE TABLE object_link (
    id               bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    link_type_id     bigint      NOT NULL REFERENCES link_type (id) ON DELETE RESTRICT,
    source_object_id bigint      NOT NULL REFERENCES object_instance (id) ON DELETE RESTRICT,
    target_object_id bigint      NOT NULL REFERENCES object_instance (id) ON DELETE RESTRICT,
    origin           varchar(20) NOT NULL,
    link_mapping_id  bigint,                              -- RULE 연결의 현재 근거 규칙 개정본(재조정 때 새 개정본으로 바뀜)
    status           varchar(20) NOT NULL DEFAULT 'ACTIVE',
    inactivated_at   timestamptz,
    evidence         jsonb       NOT NULL DEFAULT '{}'::jsonb,
    confirmed_by     bigint,                              -- → account.id (운영 ERD)
    proposal_item_id bigint,                              -- → proposal_item.id (운영 ERD)
    created_at       timestamptz NOT NULL DEFAULT now(),
    updated_at       timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT uq_object_link UNIQUE (link_type_id, source_object_id, target_object_id),
    CONSTRAINT uq_object_link_source UNIQUE (id, source_object_id, link_type_id),   -- 운영 held_item 복합 FK용
    -- 연결을 만든 규칙의 관계 유형이 연결의 관계 유형과 같아야 한다(복합 FK로 강제)
    CONSTRAINT fk_object_link_mapping
        FOREIGN KEY (link_mapping_id, link_type_id)
        REFERENCES link_mapping (id, link_type_id) ON DELETE RESTRICT,
    CONSTRAINT ck_object_link_origin   CHECK (origin IN ('RULE', 'DOCUMENT', 'MANUAL')),
    CONSTRAINT ck_object_link_rule     CHECK (origin <> 'RULE' OR link_mapping_id IS NOT NULL),
    CONSTRAINT ck_object_link_confirm  CHECK (origin = 'RULE' OR confirmed_by IS NOT NULL),
    CONSTRAINT ck_object_link_self     CHECK (source_object_id <> target_object_id),
    CONSTRAINT ck_object_link_evidence CHECK (jsonb_typeof(evidence) = 'object'),
    -- 메모 연결은 관찰·추정 표현만. 부정 표현("3호기 아님")은 연결하지 않는다(U8 결정 2026-10-27)
    CONSTRAINT ck_object_link_document CHECK (origin <> 'DOCUMENT' OR coalesce(evidence->>'expression_kind', '') IN ('OBSERVED', 'ESTIMATED')),  -- 키가 없으면 NULL이라 coalesce
    CONSTRAINT ck_object_link_status   CHECK (status IN ('ACTIVE', 'INACTIVE')),
    CONSTRAINT ck_object_link_inactive CHECK ((status = 'INACTIVE') = (inactivated_at IS NOT NULL))
);
COMMENT ON TABLE object_link IS '확정된 객체 간 연결. 조회는 status=ACTIVE만. 보류 건·검토 중 후보는 운영 ERD. 양 끝 객체 유형이 관계 유형과 맞는지는 Handler가 검사';
COMMENT ON COLUMN object_link.status IS '[결정 U6] MVP는 새 개정본을 활성화하는 트랜잭션 안에서 동기 재조정한다(데이터가 커지면 비동기 재조정으로 전환). 새 규칙에서도 성립하면 ACTIVE 유지 + link_mapping_id를 새 개정본으로, 성립하지 않으면 INACTIVE(지우지 않음). MANUAL·DOCUMENT 연결은 재조정 대상이 아니다';
COMMENT ON COLUMN object_link.evidence IS '원천 키·변환 결과. DOCUMENT면 {원문 구간, 사건, 시간 표현, expression_kind}. [결정 U8 2026-10-27] expression_kind는 OBSERVED(관찰)·ESTIMATED(추정)만. 부정 표현은 연결하지 않고 분석 결과에만 남는다. ESTIMATED 연결은 Agent가 "추정"이라고 말한다';

-- ---------------------------------------------------------------------
-- 6. Action
-- ---------------------------------------------------------------------

CREATE TABLE action_definition (
    id                    bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    code                  varchar(100) NOT NULL UNIQUE,
    name                  varchar(200) NOT NULL,
    description           text         NOT NULL,
    target_kind           varchar(20)  NOT NULL,
    target_object_type_id bigint       REFERENCES object_type (id) ON DELETE RESTRICT,
    handler_key           varchar(200) NOT NULL,
    input_schema          jsonb        NOT NULL DEFAULT '{}'::jsonb,
    action_kind           varchar(10)  NOT NULL,
    requires_confirmation boolean      NOT NULL DEFAULT true,
    required_permission   varchar(100) NOT NULL,          -- [미정 U5] 권한 코드 체계
    is_active             boolean      NOT NULL DEFAULT true,
    created_at            timestamptz  NOT NULL DEFAULT now(),
    created_by            bigint,
    updated_at            timestamptz  NOT NULL DEFAULT now(),
    updated_by            bigint,
    row_version           integer      NOT NULL DEFAULT 0,
    CONSTRAINT ck_action_definition_target_kind CHECK (target_kind IN ('OBJECT', 'SYSTEM')),
    CONSTRAINT ck_action_definition_target      CHECK ((target_kind = 'OBJECT') = (target_object_type_id IS NOT NULL)),
    CONSTRAINT ck_action_definition_kind        CHECK (action_kind IN ('READ', 'WRITE')),
    CONSTRAINT ck_action_definition_schema      CHECK (jsonb_typeof(input_schema) = 'object')
);
COMMENT ON TABLE action_definition IS '실행 가능한 기능의 계약. 실행 이력은 운영 ERD. [미정 U9] 온톨로지 AI·에이전트 AI Action 구분';

-- ---------------------------------------------------------------------
-- 7. 인덱스 (PostgreSQL은 FK 인덱스를 자동으로 만들지 않는다)
-- ---------------------------------------------------------------------

CREATE INDEX ix_property_definition_type    ON property_definition (object_type_id);
CREATE INDEX ix_link_type_source            ON link_type (source_type_id);
CREATE INDEX ix_link_type_target            ON link_type (target_type_id);
CREATE INDEX ix_source_column_resource      ON source_column (source_resource_id);
CREATE INDEX ix_source_preview_queue        ON source_preview (requested_at) WHERE status = 'QUEUED';   -- 배치가 가져갈 작업
CREATE INDEX ix_source_preview_expires      ON source_preview (expires_at);                             -- 만료 삭제
CREATE INDEX ix_source_preview_resource     ON source_preview (source_resource_id);
CREATE INDEX ix_object_source_mapping_res   ON object_source_mapping (source_resource_id);
CREATE INDEX ix_object_source_mapping_type  ON object_source_mapping (object_type_id);
CREATE INDEX ix_property_source_mapping_prop ON property_source_mapping (property_definition_id);
CREATE INDEX ix_property_source_mapping_col ON property_source_mapping (source_column_id);
CREATE INDEX ix_link_mapping_type           ON link_mapping (link_type_id);
CREATE INDEX ix_link_mapping_condition_src  ON link_mapping_condition (source_property_id);
CREATE INDEX ix_link_mapping_condition_tgt  ON link_mapping_condition (target_property_id);
CREATE INDEX ix_sync_run_source_requested   ON sync_run (data_source_id, requested_at DESC);
CREATE INDEX ix_sync_run_resource_resource  ON sync_run_resource (source_resource_id, started_at DESC);
CREATE INDEX ix_object_instance_type_status ON object_instance (object_type_id, status);
CREATE INDEX ix_object_instance_sync_run    ON object_instance (last_sync_run_id);
-- jsonb_path_ops는 포함 검색(properties @> '{"code":"PR-03"}')만 지원한다. 부분 일치·범위 검색은 아래 trgm 또는
-- 실제 쿼리가 정해진 뒤 자주 쓰는 속성의 표현식 인덱스(예: ((properties->>'capacity_ton')::numeric))로 추가한다
CREATE INDEX ix_object_instance_properties  ON object_instance USING gin (properties jsonb_path_ops);
CREATE INDEX ix_object_instance_name_trgm   ON object_instance USING gin (display_name gin_trgm_ops);  -- 이름·번호 부분 검색(FN-EXP-01)
-- 조회는 ACTIVE 연결만 쓰므로 탐색 인덱스는 부분 인덱스로 둔다
CREATE INDEX ix_object_link_source          ON object_link (source_object_id, link_type_id) WHERE status = 'ACTIVE';
CREATE INDEX ix_object_link_target          ON object_link (target_object_id, link_type_id) WHERE status = 'ACTIVE';
CREATE INDEX ix_object_link_mapping         ON object_link (link_mapping_id);
CREATE INDEX ix_property_source_mapping_res ON property_source_mapping (source_resource_id);
CREATE INDEX ix_action_definition_target    ON action_definition (target_object_type_id);
